#![no_std]
use soroban_sdk::{
    contract, contracterror, contractimpl, contracttype, panic_with_error, token, Address, Env,
};

// Ledgers are about five seconds apart. Balances are kept alive for at least 60 days.
const DAY_IN_LEDGERS: u32 = 17_280;
const TTL_THRESHOLD: u32 = 30 * DAY_IN_LEDGERS;
const TTL_EXTEND_TO: u32 = 60 * DAY_IN_LEDGERS;

#[contracterror]
#[derive(Copy, Clone, Debug, Eq, PartialEq)]
#[repr(u32)]
pub enum Error {
    InvalidAmount = 1,
    InsufficientStake = 2,
}

#[contracttype]
#[derive(Clone)]
pub enum DataKey {
    /// Address of the staked token (its Stellar Asset Contract for native XLM). Instance storage.
    Token,
    /// Sum of every user's stake. Instance storage.
    Total,
    /// One user's stake. Persistent storage.
    Staked(Address),
}

#[contract]
pub struct Staking;

#[contractimpl]
impl Staking {
    /// Runs once at deploy time. `token` is the contract address of the asset users stake,
    /// for native XLM the Stellar Asset Contract (`stellar contract id asset --asset native`).
    pub fn __constructor(env: Env, token: Address) {
        env.storage().instance().set(&DataKey::Token, &token);
        env.storage().instance().set(&DataKey::Total, &0_i128);
        env.storage()
            .instance()
            .extend_ttl(TTL_THRESHOLD, TTL_EXTEND_TO);
    }

    /// Moves `amount` of the token from `user` into this contract and credits `user`.
    pub fn stake(env: Env, user: Address, amount: i128) {
        user.require_auth();
        if amount <= 0 {
            panic_with_error!(&env, Error::InvalidAmount);
        }

        token_client(&env).transfer(&user, &env.current_contract_address(), &amount);

        let key = DataKey::Staked(user.clone());
        let current: i128 = env.storage().persistent().get(&key).unwrap_or(0);
        env.storage().persistent().set(&key, &(current + amount));
        env.storage()
            .persistent()
            .extend_ttl(&key, TTL_THRESHOLD, TTL_EXTEND_TO);

        set_total(&env, total_staked_inner(&env) + amount);
    }

    /// Debits `amount` from `user`'s stake and sends the token back to `user`.
    /// Fails if `user` has less than `amount` staked.
    pub fn unstake(env: Env, user: Address, amount: i128) {
        user.require_auth();
        if amount <= 0 {
            panic_with_error!(&env, Error::InvalidAmount);
        }

        let key = DataKey::Staked(user.clone());
        let current: i128 = env.storage().persistent().get(&key).unwrap_or(0);
        if current < amount {
            panic_with_error!(&env, Error::InsufficientStake);
        }

        env.storage().persistent().set(&key, &(current - amount));
        env.storage()
            .persistent()
            .extend_ttl(&key, TTL_THRESHOLD, TTL_EXTEND_TO);
        set_total(&env, total_staked_inner(&env) - amount);

        token_client(&env).transfer(&env.current_contract_address(), &user, &amount);
    }

    /// The amount `user` has staked (0 if none).
    pub fn staked(env: Env, user: Address) -> i128 {
        env.storage()
            .persistent()
            .get(&DataKey::Staked(user))
            .unwrap_or(0)
    }

    /// The amount staked by everyone.
    pub fn total_staked(env: Env) -> i128 {
        total_staked_inner(&env)
    }
}

fn token_client(env: &Env) -> token::TokenClient<'_> {
    let token: Address = env
        .storage()
        .instance()
        .get(&DataKey::Token)
        .expect("token is set by the constructor");
    token::TokenClient::new(env, &token)
}

fn total_staked_inner(env: &Env) -> i128 {
    env.storage().instance().get(&DataKey::Total).unwrap_or(0)
}

fn set_total(env: &Env, total: i128) {
    env.storage().instance().set(&DataKey::Total, &total);
    env.storage()
        .instance()
        .extend_ttl(TTL_THRESHOLD, TTL_EXTEND_TO);
}

mod test;
EOF
