#![cfg(test)]

use super::*;
use soroban_sdk::{
    testutils::Address as _,
    token::{StellarAssetClient, TokenClient},
    Address, Env,
};

/// Registers a token (a Stellar Asset Contract, like native XLM) and the staking contract.
/// Returns the staking contract's address and the token's address.
fn setup(env: &Env) -> (Address, Address) {
    env.mock_all_auths();
    let admin = Address::generate(env);
    let token_id = env.register_stellar_asset_contract_v2(admin).address();
    let contract_id = env.register(Staking, (token_id.clone(),));
    (contract_id, token_id)
}

fn mint(env: &Env, token_id: &Address, to: &Address, amount: i128) {
    StellarAssetClient::new(env, token_id).mint(to, &amount);
}

#[test]
fn stake_moves_tokens_and_records_the_stake() {
    let env = Env::default();
    let (contract_id, token_id) = setup(&env);
    let client = StakingClient::new(&env, &contract_id);
    let token = TokenClient::new(&env, &token_id);
    let user = Address::generate(&env);
    mint(&env, &token_id, &user, 1_000);

    client.stake(&user, &400);

    assert_eq!(client.staked(&user), 400);
    assert_eq!(client.total_staked(), 400);
    assert_eq!(token.balance(&user), 600);
    assert_eq!(token.balance(&contract_id), 400);
}

#[test]
fn stakes_add_up_and_totals_include_every_user() {
    let env = Env::default();
    let (contract_id, token_id) = setup(&env);
    let client = StakingClient::new(&env, &contract_id);
    let alice = Address::generate(&env);
    let bob = Address::generate(&env);
    mint(&env, &token_id, &alice, 1_000);
    mint(&env, &token_id, &bob, 1_000);

    client.stake(&alice, &100);
    client.stake(&alice, &50);
    client.stake(&bob, &25);

    assert_eq!(client.staked(&alice), 150);
    assert_eq!(client.staked(&bob), 25);
    assert_eq!(client.total_staked(), 175);
}

#[test]
fn unstake_returns_tokens_and_reduces_the_stake() {
    let env = Env::default();
    let (contract_id, token_id) = setup(&env);
    let client = StakingClient::new(&env, &contract_id);
    let token = TokenClient::new(&env, &token_id);
    let user = Address::generate(&env);
    mint(&env, &token_id, &user, 1_000);
    client.stake(&user, &400);

    client.unstake(&user, &150);

    assert_eq!(client.staked(&user), 250);
    assert_eq!(client.total_staked(), 250);
    assert_eq!(token.balance(&user), 750);
    assert_eq!(token.balance(&contract_id), 250);
}

#[test]
fn unstake_the_whole_stake() {
    let env = Env::default();
    let (contract_id, token_id) = setup(&env);
    let client = StakingClient::new(&env, &contract_id);
    let user = Address::generate(&env);
    mint(&env, &token_id, &user, 500);
    client.stake(&user, &500);

    client.unstake(&user, &500);

    assert_eq!(client.staked(&user), 0);
    assert_eq!(client.total_staked(), 0);
    assert_eq!(TokenClient::new(&env, &token_id).balance(&user), 500);
}

#[test]
#[should_panic(expected = "Error(Contract, #2)")]
fn unstake_more_than_staked_fails() {
