import { connection } from "next/server";
import { Suspense } from "react";
import { stakingClient } from "@/lib/contracts";
import { stellar } from "@/lib/stellar";

type Outcome = { value: string } | { error: string };

function errorText(error: unknown, rpcUrl: string | undefined): string {
  // Some network errors arrive with an empty message; fall back to their text, and say where we called.
  const reason = (error instanceof Error && error.message) || String(error) || "unknown error";
  return `${reason} (RPC: ${rpcUrl ?? "not set"})`;
}

async function readTotalStaked(): Promise<Outcome> {
  try {
    const { result } = await stakingClient().total_staked();
    return { value: result.toString() };
  } catch (error) {
    return { error: errorText(error, stellar.rpcUrl) };
  }
}

async function readStaked(address: string): Promise<Outcome> {
  try {
    const { result } = await stakingClient().staked({ user: address });
    return { value: result.toString() };
  } catch (error) {
    return { error: errorText(error, stellar.rpcUrl) };
  }
}

async function TotalStaked() {
  // Read the contract when a request arrives, not while `next build` prerenders the page.
  await connection();
  const outcome = await readTotalStaked();
  if ("error" in outcome) {
    return <p data-testid="total-staked-error">Could not read the contract: {outcome.error}</p>;
  }
  return <p data-testid="total-staked">{outcome.value}</p>;
}

async function StakedBy({ searchParams }: { searchParams: Promise<{ address?: string | string[] }> }) {
  const { address: raw } = await searchParams;
  const address = Array.isArray(raw) ? raw[0] : raw;
  if (!address) {
    return <p>Add <code>?address=G…</code> to the URL to see one account&apos;s stake.</p>;
  }
  const outcome = await readStaked(address);
  return (
    <>
      <p>
        Staked by <code>{address}</code>:
      </p>
      {"error" in outcome ? (
        <p data-testid="staked-error">Could not read the contract: {outcome.error}</p>
      ) : (
        <p data-testid="staked-amount">{outcome.value}</p>
      )}
    </>
  );
}

export default function StakingPage({
  searchParams,
}: {
  searchParams: Promise<{ address?: string | string[] }>;
}) {
  return (
    <main>
      <h1>Staking</h1>
      <p>
        Network: <code>{stellar.network}</code>. Amounts are in stroops (1 XLM = 10,000,000).
      </p>
      <h2>Total staked</h2>
      <Suspense fallback={<p>Reading the contract…</p>}>
        <TotalStaked />
      </Suspense>
      <h2>Account stake</h2>
      <Suspense fallback={<p>Reading the contract…</p>}>
        <StakedBy searchParams={searchParams} />
      </Suspense>
    </main>
  );
}
